--
-- Table structure for table `audio_files`
--

DROP TABLE IF EXISTS `audio_files`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audio_files` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `party_id` varchar(100) NOT NULL,
  `ingest_log_id` bigint(20) unsigned NOT NULL,
  `track_id` int(10) unsigned NOT NULL,
  `asset_class` enum('Master','StreamingProfile','Ephemeral') NOT NULL DEFAULT 'Master',
  `asset_subtype` varchar(50) DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL COMMENT 'For TTL cleanup of Ephemeral assets',
  `original_filename` varchar(512) NOT NULL,
  `stored_path` varchar(1024) NOT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size_bytes` bigint(20) unsigned DEFAULT NULL,
  `checksum_md5` varchar(64) DEFAULT NULL,
  `checksum_sha256` varchar(128) DEFAULT NULL,
  `duration_seconds` int(10) unsigned DEFAULT NULL,
  `audio_codec` varchar(50) DEFAULT NULL,
  `sample_rate` int(10) unsigned DEFAULT NULL,
  `bit_depth` smallint(5) unsigned DEFAULT NULL,
  `channels` tinyint(3) unsigned DEFAULT NULL,
  `bitrate_kbps` smallint(5) unsigned DEFAULT NULL,
  `ddex_resource_ref` varchar(100) DEFAULT NULL,
  `partner_id` int(10) unsigned NOT NULL DEFAULT 1 COMMENT 'Multi-tenant isolation (W1-4)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_audio_path` (`stored_path`(512)),
  KEY `idx_audio_track` (`track_id`),
  KEY `idx_audio_expires` (`expires_at`),
  KEY `idx_audio_partner` (`partner_id`),
  KEY `party_id` (`party_id`),
  KEY `ingest_log_id` (`ingest_log_id`),
  KEY `ix_audio_files_asset_subtype` (`asset_subtype`),
  CONSTRAINT `audio_files_ibfk_1` FOREIGN KEY (`party_id`) REFERENCES `parties` (`party_id`),
  CONSTRAINT `audio_files_ibfk_2` FOREIGN KEY (`ingest_log_id`) REFERENCES `ingest_logs` (`id`),
  CONSTRAINT `audio_files_ibfk_3` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `audio_files_ibfk_4` FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1069 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
