/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `consumption_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_category` enum('stream_start','stream_complete','stream_skip','download_success') NOT NULL,
  `track_id` int(10) unsigned DEFAULT NULL,
  `isrc` varchar(15) DEFAULT NULL COMMENT 'Denormalized heavily for rapid DSRF generation indexing',
  `label_id` int(10) unsigned DEFAULT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
  `country_code` char(2) DEFAULT NULL COMMENT 'Geolocated user state from start IP',
  `client_ip` varchar(45) DEFAULT NULL COMMENT 'Hashed or raw IP for fraud analysis',
  `playback_context` varchar(50) DEFAULT NULL COMMENT 'e.g., search, playlist, artist_profile',
  `source_device` enum('web','ios','android','desktop','other') DEFAULT 'web',
  `partner_id` int(10) unsigned NOT NULL DEFAULT 1 COMMENT 'Multi-tenant isolation (W1-4)',
  `session_id` char(36) DEFAULT NULL COMMENT 'Cryptographic session. Identifies and deduplicates bot-farms.',
  `duration_seconds` int(10) unsigned NOT NULL,
  `event_timestamp` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_agg_label` (`label_id`,`event_category`,`event_timestamp`),
  KEY `idx_agg_isrc` (`isrc`,`event_category`,`event_timestamp`),
  KEY `idx_ce_session` (`session_id`),
  KEY `idx_ce_partner` (`partner_id`),
  KEY `idx_dsrf_report` (`label_id`,`event_timestamp`,`isrc`,`country_code`,`event_category`),
  KEY `track_id` (`track_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `consumption_events_ibfk_1` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `consumption_events_ibfk_2` FOREIGN KEY (`label_id`) REFERENCES `labels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `consumption_events_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `consumption_events_ibfk_4` FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=179 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
