--
-- Table structure for table `ingestion_errors`
--

DROP TABLE IF EXISTS `ingestion_errors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ingestion_errors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ingest_log_id` bigint(20) unsigned NOT NULL,
  `partner_id` int(10) unsigned NOT NULL DEFAULT 1 COMMENT 'Multi-tenant isolation (W1-4)',
  `error_code` varchar(50) NOT NULL,
  `error_severity` enum('warning','critical') DEFAULT 'critical',
  `reference_node` varchar(255) DEFAULT NULL COMMENT 'E.g., <ReleaseId> or specific ISRC string',
  `error_message` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ingest_log_id` (`ingest_log_id`),
  KEY `idx_ie_severity` (`error_severity`),
  KEY `idx_ie_partner` (`partner_id`),
