--
-- Table structure for table `releases`
--

DROP TABLE IF EXISTS `releases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `releases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `label_id` int(10) unsigned DEFAULT NULL,
  `party_id` varchar(100) NOT NULL,
  `message_id` varchar(255) NOT NULL,
  `release_ref` varchar(100) DEFAULT NULL,
  `ern_version` varchar(10) DEFAULT NULL,
  `raw_xml_path` varchar(500) DEFAULT NULL,
  `icpn` varchar(30) DEFAULT NULL,
  `upc_ean` varchar(20) DEFAULT NULL,
  `grid` varchar(30) DEFAULT NULL,
  `catalog_number` varchar(100) DEFAULT NULL,
  `title` varchar(1024) NOT NULL,
  `subtitle` varchar(1024) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `display_artist` varchar(512) DEFAULT NULL,
  `partner_id` int(10) unsigned NOT NULL DEFAULT 1,
  `release_type` enum('Album','EP','Single') DEFAULT 'Album',
  `release_date` date DEFAULT NULL,
  `original_release_date` date DEFAULT NULL,
  `ingested_at` datetime DEFAULT current_timestamp(),
  `p_line_year` year(4) DEFAULT NULL,
  `p_line_text` varchar(512) DEFAULT NULL,
  `c_line_year` year(4) DEFAULT NULL,
  `c_line_text` varchar(512) DEFAULT NULL,
  `p_line` varchar(255) DEFAULT NULL,
  `c_line` varchar(255) DEFAULT NULL,
  `genre_id` int(10) unsigned DEFAULT NULL,
  `sub_genre_id` int(10) unsigned DEFAULT NULL,
  `parental_warning` enum('NoAdviceAvailable','NotExplicit','Explicit','ExplicitContentEdited') DEFAULT 'NotExplicit',
  `is_compilation` tinyint(1) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `price_cents` int(10) unsigned DEFAULT NULL,
  `cover_image` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_release_label` (`label_id`),
  KEY `idx_release_catalog` (`catalog_number`),
  KEY `idx_release_active` (`is_active`),
  KEY `idx_icpn` (`icpn`),
  KEY `idx_party` (`party_id`),
  KEY `idx_message` (`message_id`),
  KEY `idx_release_genre` (`genre_id`),
  KEY `idx_release_sub_genre` (`sub_genre_id`),
  KEY `fk_release_partner` (`partner_id`),
  CONSTRAINT `fk_release_genre` FOREIGN KEY (`genre_id`) REFERENCES `genres` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_release_label` FOREIGN KEY (`label_id`) REFERENCES `labels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_release_message` FOREIGN KEY (`message_id`) REFERENCES `messages` (`message_id`),
  CONSTRAINT `fk_release_partner` FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`),
  CONSTRAINT `fk_release_party` FOREIGN KEY (`party_id`) REFERENCES `parties` (`party_id`),
  CONSTRAINT `fk_release_sub_genre` FOREIGN KEY (`sub_genre_id`) REFERENCES `genres` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=509 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

