--
-- Table structure for table `track_contributors`
--

DROP TABLE IF EXISTS `track_contributors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `track_contributors` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `track_id` int(10) unsigned NOT NULL,
  `person_id` int(10) unsigned NOT NULL,
  `role` enum('MainArtist','FeaturedArtist','Remixer','Conductor','Orchestra','Soloist','Composer','Lyricist','ComposerLyricist','Arranger','Producer','ExecutiveProducer','MixEngineer','MasteringEngineer','RecordingEngineer','MusicPublisher','SubPublisher','AdministratingPublisher','Other') NOT NULL,
  `royalty_type` enum('MasterRights','NeighboringRights','Mechanical','Performance','Producer','Sync','Other') NOT NULL,
  `ownership_share` decimal(8,5) DEFAULT NULL,
  `sequence_num` smallint(5) unsigned DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_participant` (`track_id`,`person_id`,`role`),
  KEY `idx_recording` (`track_id`),
  KEY `idx_person` (`person_id`),
  KEY `idx_role` (`role`),
  CONSTRAINT `track_contributors_ibfk_1` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `track_contributors_ibfk_2` FOREIGN KEY (`person_id`) REFERENCES `contributors` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=854 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

