--
-- Table structure for table `track_processing_status`
--

DROP TABLE IF EXISTS `track_processing_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `track_processing_status` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `track_id` int(10) unsigned NOT NULL,
  `partner_id` int(10) unsigned NOT NULL DEFAULT 1,
  `ingest_log_id` bigint(20) unsigned DEFAULT NULL,
  `audio_filename` varchar(512) DEFAULT NULL,
  `sftp_env` varchar(16) NOT NULL DEFAULT 'live',
  `embedding_status` varchar(20) NOT NULL DEFAULT 'pending',
  `peaks_status` varchar(20) NOT NULL DEFAULT 'pending',
  `segments_status` varchar(20) NOT NULL DEFAULT 'pending',
  `faiss_indexed` tinyint(1) NOT NULL DEFAULT 0,
  `embedding_error` text DEFAULT NULL,
  `peaks_error` text DEFAULT NULL,
  `segments_error` text DEFAULT NULL,
  `embedding_completed_at` datetime DEFAULT NULL,
  `peaks_completed_at` datetime DEFAULT NULL,
  `segments_completed_at` datetime DEFAULT NULL,
  `faiss_indexed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tps_track` (`track_id`),
  KEY `ix_tps_partner` (`partner_id`),
  KEY `ix_tps_ingest_log` (`ingest_log_id`),
  KEY `ix_tps_embedding_status` (`embedding_status`),
  KEY `ix_tps_faiss_indexed` (`faiss_indexed`),
  CONSTRAINT `fk_tps_ingest_log` FOREIGN KEY (`ingest_log_id`) REFERENCES `ingest_logs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tps_partner` FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`),
  CONSTRAINT `fk_tps_track` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=133 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

