--
-- Table structure for table `tracks`
--

DROP TABLE IF EXISTS `tracks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tracks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(36) NOT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
  `party_id` varchar(100) DEFAULT NULL,
  `resource_ref` varchar(100) DEFAULT NULL,
  `proprietary_id` varchar(100) DEFAULT NULL,
  `isrc` varchar(30) NOT NULL,
  `title` varchar(1024) NOT NULL,
  `version_title` varchar(512) DEFAULT NULL,
  `display_artist` varchar(512) DEFAULT NULL,
  `partner_id` int(10) unsigned NOT NULL DEFAULT 1,
  `duration_ms` int(10) unsigned DEFAULT NULL,
  `bpm` smallint(5) unsigned DEFAULT NULL,
  `musical_key` varchar(10) DEFAULT NULL,
  `key_signature` varchar(10) DEFAULT NULL,
  `audio_language` char(2) DEFAULT 'xx',
  `language_of_lyrics` varchar(10) DEFAULT NULL,
  `genre_id` int(10) unsigned DEFAULT NULL,
  `sub_genre_id` int(10) unsigned DEFAULT NULL,
  `price_cents` int(10) unsigned DEFAULT 99,
  `mix_name` varchar(150) DEFAULT 'Original Mix',
  `type` varchar(50) DEFAULT 'electrobuzz',
  `p_line_year` year(4) DEFAULT NULL,
  `p_line_text` varchar(512) DEFAULT NULL,
  `deal_terms` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`deal_terms`)),
  `parental_warning` enum('NoAdviceAvailable','NotExplicit','Explicit','ExplicitContentEdited') DEFAULT 'NotExplicit',
  `is_explicit` tinyint(1) DEFAULT 0,
