  `is_favorite` tinyint(1) NOT NULL DEFAULT 0,
  `is_following` tinyint(1) NOT NULL DEFAULT 0,
  `favorite_at` datetime DEFAULT NULL,
  `unfavorite_at` datetime DEFAULT NULL,
  `followed_at` datetime DEFAULT NULL,
  `unfollowed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`,`track_id`),
  KEY `track_id` (`track_id`),
  CONSTRAINT `user_track_engagements_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_track_engagements_ibfk_2` FOREIGN KEY (`track_id`) REFERENCES `tracks` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
