--
-- Table structure for table `webhook_delivery_logs`
--

DROP TABLE IF EXISTS `webhook_delivery_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `webhook_delivery_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `correlation_id` char(36) DEFAULT NULL,
  `webhook_id` int(10) unsigned NOT NULL,
  `partner_id` int(10) unsigned NOT NULL,
  `event_type` varchar(64) NOT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`payload`)),
  `attempt_number` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `response_status` smallint(6) DEFAULT NULL,
  `response_latency_ms` int(10) unsigned DEFAULT NULL,
  `error_message` text DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `webhook_id` (`webhook_id`),
  KEY `idx_delivery_partner_event` (`partner_id`,`event_type`,`created_at`),
  KEY `idx_delivery_status` (`response_status`,`created_at`),
  CONSTRAINT `webhook_delivery_logs_ibfk_1` FOREIGN KEY (`webhook_id`) REFERENCES `partner_webhooks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `webhook_delivery_logs_ibfk_2` FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

